JOIN #TempRefCusPreference tmpRefTbl ON tmpTbl.ZX1_ZZS_Preference = tmpRefTbl.ZZS_PK
JOIN RefCusPreference refTbl ON ((refTbl.ZZS_ZZZ_NKDataGrouping = tmpRefTbl.ZZS_ZZZ_NKDataGrouping) AND (refTbl.ZZS_Preference = tmpRefTbl.ZZS_Preference));


UPDATE tmpTbl SET tmpTbl.ZZT_ZZA_TradeGroup = refTbl.ZZA_PK
FROM #TempRefCusApplicability tmpTbl 
JOIN #TempRefCusTradeGroup tmpRefTbl ON tmpTbl.ZZT_ZZA_TradeGroup = tmpRefTbl.ZZA_PK
JOIN RefCusTradeGroup refTbl ON ((refTbl.ZZA_ZZZ_NKDataGrouping = tmpRefTbl.ZZA_ZZZ_NKDataGrouping) AND (refTbl.ZZA_TradeGroup = tmpRefTbl.ZZA_TradeGroup));

UPDATE tmpTbl SET tmpTbl.ZZT_ZZA_SecondTradeGroup = refTbl.ZZA_PK
