JOIN RefCusTradeGroup refTbl ON ((refTbl.ZZA_ZZZ_NKDataGrouping = tmpRefTbl.ZZA_ZZZ_NKDataGrouping) AND (refTbl.ZZA_TradeGroup = tmpRefTbl.ZZA_TradeGroup));


