FROM RefCusTariff AS t
JOIN #TempRefCusTariff AS s ON (((t.ZZ1_ZZZ_NKDataGrouping = s.ZZ1_ZZZ_NKDataGrouping) AND (t.ZZ1_TariffCode = s.ZZ1_TariffCode) AND (t.ZZ1_ZZI_TariffType = s.ZZ1_ZZI_TariffType) AND (t.ZZ1_EndDate = s.ZZ1_EndDate) AND (t.ZZ1_IAMUnique = s.ZZ1_IAMUnique)) OR ((t.ZZ1_ZZZ_NKDataGrouping = s.ZZ1_ZZZ_NKDataGrouping) AND (t.ZZ1_TariffCode = s.ZZ1_TariffCode) AND (t.ZZ1_ZZI_TariffType = s.ZZ1_ZZI_TariffType) AND (t.ZZ1_StartDate = s.ZZ1_StartDate) AND (t.ZZ1_IAMUnique = s.ZZ1_IAMUnique))) ;


